#include "projection_phased_cases.h"
unsigned pjp_apply(projection_case *c,uint8_t phase){p66_preparation *s=&c->previous.previous.base.previous.previous.previous.preparation;p66_scale_scratch *sc=&c->previous.previous.base.previous.previous.previous.scratch;p66_elapsed_state *el=&c->previous.previous.base.previous.elapsed;p66_divide_scratch *d=&c->previous.previous.base.scratch;p66_norm_scratch *n=&c->previous.previous.norm;p66_pushdown *p=&c->previous.previous.base.previous.previous.push;if(!phase)return (unsigned)p66_projection_trig_phase(s,sc,d,n,p,&c->previous.trig,c->previous.cdu);if(phase==1u)return (unsigned)p66_projection_rotation_phase(s,sc,el,d,n,p,&c->previous.trig,&c->rotation);return (unsigned)p66_projection_dot_phase(s,sc,el,d,n,p,&c->previous.trig);}
